  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      asanaAccessToken: 'test-token',
      asanaWorkspaceGid: '67890',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as JotformWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.taskGid).toBe('987654321')
  })
})

describe('handle', () => {
  it('creates an Asana task with form_response answers', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      expect(req.method).toBe('POST')
      expect(req.url).toBe('https://app.asana.com/api/1.0/tasks')
