      expect(req.json).toEqual({
        data: {
          workspace: '67890',
          name: 'New task from Jotform - Contact Form',
          notes: 'Form answers:\nName: John Doe\nEmail: john@example.com\nMessage: Hello world',
        },
      })
      return jsonResponse(TARGET_ENDPOINTS[0].response)
    })

    const payload: JotformWebhookPayload = {
      id: '1234567890',
      form_id: '54321',
      form_title: 'Contact Form',
      submitted_at: '2026-02-23T17:23:00+00:00',
      ip: '203.0.113.42',
      form_response: {
        q1_name: 'John Doe',
        q2_email: 'john@example.com',
        q3_message: 'Hello world',
      },
    }

    const result = await handle(payload, {
      asanaAccessToken: 'test-token',
      asanaWorkspaceGid: '67890',
      fetch,
    })

    expect(result.taskGid).toBe('987654321')
    expect(calls.length).toBe(1)
  })

  it('creates an Asana task with field_{id}_answer answers', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      expect(req.json).toEqual({
        data: {
          workspace: '67890',
          name: 'New task from Jotform - Survey',
          notes: 'Form answers:\nField 1: Answer One\nField 2: Answer Two',
        },
      })
      return jsonResponse({ data: { gid: '111222333' } })
    })

    const payload: JotformWebhookPayload = {
      id: '999',
      form_id: '111',
      form_title: 'Survey',
      submitted_at: '2026-01-01T00:00:00Z',
      ip: '1.2.3.4',
      field_1_answer: 'Answer One',
      field_2_answer: 'Answer Two',
    }

    const result = await handle(payload, {
      asanaAccessToken: 'test-token',
      asanaWorkspaceGid: '67890',
      fetch,
    })

    expect(result.taskGid).toBe('111222333')
    expect(calls.length).toBe(1)
  })

  it('uses custom taskNamePrefix when provided', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      expect((req.json as any).data.name).toBe('Custom Prefix - Contact Form')
